const op=v=>typeof v==='string'&&/^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$/.test(v);
const encode=s=>new TextEncoder().encode(s);
const hex=bytes=>Array.from(bytes,n=>n.toString(16).padStart(2,'0')).join('');
