async function verifyObject(db,data){validateData(data,['sha256','expected_cursor']);if(!hash(data.sha256)||!integer(data.expected_cursor,MAIN_STORE_LIMITS.object_chunks))fail('Invalid object verification cursor');const saved=await first(db,'SELECT descriptor,cursor,hash_state,utf8_state,verified FROM ms_objects WHERE namespace=? AND sha256=?',NS,data.sha256);if(!saved)fail('Object not found',404);if(saved.verified||saved.cursor!==data.expected_cursor)return {sha256:data.sha256,cursor:saved.cursor,verified:!!saved.verified,idempotent:true};const descriptor=JSON.parse(saved.descriptor),state=new IncrementalSHA256(JSON.parse(saved.hash_state)),utf8=JSON.parse(saved.utf8_state);let cursor=saved.cursor;for(const part of descriptor.chunks.slice(cursor,cursor+MAIN_STORE_LIMITS.verify_chunks)){const chunk=await first(db,'SELECT data_base64,bytes FROM ms_chunks WHERE namespace=? AND sha256=?',NS,part.sha256);if(!chunk||chunk.bytes!==part.bytes)fail('Object chunk missing',409);const bytes=base64Bytes(chunk.data_base64);if(await sha(bytes)!==part.sha256)fail('Object chunk checksum mismatch',409);state.update(bytes);updateUTF8(utf8,bytes);cursor++;}const done=cursor===descriptor.chunks.length;if(done&&(state.length!==descriptor.bytes||state.digest()!==descriptor.sha256))fail('Whole-object checksum mismatch',409);await statement(db,'UPDATE ms_objects SET cursor=?,hash_state=?,utf8_state=?,valid_utf8=?,verified=? WHERE namespace=? AND sha256=? AND cursor=? AND hash_state=? AND verified=0',cursor,canonicalJSON(state.state()),canonicalJSON(utf8),done&&utf8.valid&&utf8.needed===0?1:0,done?1:0,NS,data.sha256,saved.cursor,saved.hash_state).run();const current=await first(db,'SELECT cursor,verified FROM ms_objects WHERE namespace=? AND sha256=?',NS,data.sha256);return {sha256:data.sha256,cursor:current.cursor,verified:!!current.verified};}
