async function commitOperations(db,data){validateData(data,['expected_revision','operation_id','mutations'],['files','watermarks']);if(!Array.isArray(data.mutations)||!Array.isArray(data.files??[])||data.mutations.length+(data.files?.length||0)>MAIN_STORE_LIMITS.rows)fail('Use staged operations for larger atomic changes');const files=data.files??[],base=await pin(db,data.expected_revision),wm=data.watermarks??base.watermarks,entries=[];for(const mutation of data.mutations){const row=mutation.row??mutation;entries.push([row.table+':'+row.key_sha256,await sha(canonicalJSON(mutation))]);}for(const file of files)entries.push(['~file:'+file.path,await sha(canonicalJSON(file))]);entries.sort((a,b)=>a[0]<b[0]?-1:a[0]>b[0]?1:0);let chain=EMPTY;for(const [key,digest]of entries)chain=await sha(chain+'\n'+key+'\n'+digest);const begin={operation_id:data.operation_id,expected_revision:data.expected_revision,mutation_count:data.mutations.length,file_count:files.length,watermarks:wm,chain_sha256:chain};const started=await beginOperation(db,begin);if(started.ok)return started;if(entries.length)await stageOperation(db,{operation_id:data.operation_id,batch_id:'direct',mutations:data.mutations,files});await verifyOperation(db,{operation_id:data.operation_id,expected_cursor:''});return commitStagedOperation(db,{operation_id:data.operation_id});}
