 const jobCondition="l.status IN ('imported','exported') OR l.key_sha256 IN ("+latest('agent_jobs','created_at','1',20)+')';
 if(!scope)return {sql:'1',args:[]};if(scope==='runtime_meta'){if(!op(data.operation_id))fail('Runtime metadata needs operation ID');return {sql:`(substr(json_extract(r.projection,'$.key'),1,24)='cloud_runtime_operation:' AND (json_extract(r.projection,'$.key')=? OR COALESCE(json_extract(r.projection,'$._runtime_phase'),'unknown')<>'imported')) OR json_extract(r.projection,'$.key')=? OR substr(json_extract(r.projection,'$.key'),1,length(?))=? OR (substr(json_extract(r.projection,'$.key'),1,14)<>'cloud_runtime_' AND substr(json_extract(r.projection,'$.key'),1,22)<>'cloud_official_import:')`,args:['cloud_runtime_operation:'+data.operation_id,'cloud_runtime_export:'+data.operation_id,'cloud_official_import:'+data.operation_id+'.official.','cloud_official_import:'+data.operation_id+'.official.']};}
