 if(scope==='abstract_retry')return {sql:`r.key_sha256 IN (SELECT key_sha256 FROM (SELECT key_sha256,ROW_NUMBER() OVER(PARTITION BY identity ORDER BY json_extract(projection,'$.attempted_at') DESC,CAST(json_extract(projection,'$._rowid') AS INTEGER) DESC) n FROM live WHERE table_name='abstract_attempts' AND identity IN (SELECT identity FROM candidate_papers)) WHERE n=1 UNION SELECT key_sha256 FROM (SELECT key_sha256,ROW_NUMBER() OVER(PARTITION BY identity,provider ORDER BY json_extract(projection,'$.attempted_at') DESC,CAST(json_extract(projection,'$._rowid') AS INTEGER) DESC) n FROM live WHERE table_name='abstract_attempts' AND identity IN (SELECT identity FROM candidate_papers) AND status IN ('failed','not_found')) WHERE n=1)`,args:[]};
 if(scope==='ui_jobs')return {sql:`r.status IN ('imported','exported') OR r.key_sha256 IN (${latest('agent_jobs','created_at','1',20)})`,args:[]};
