 if(scope==='runtime_run_papers')return {sql:`r.run_id=? OR r.run_id IN (SELECT l.run_id FROM live l WHERE l.table_name='agent_jobs' AND l.status='exported') OR (json_extract(r.projection,'$.role') IN ('selected','selected_new') AND r.run_id IN (SELECT l.run_id FROM live l WHERE l.table_name='agent_jobs' AND l.key_sha256 IN (${latest('agent_jobs','imported_at',"l.status='imported'")})))`,args:[data.current_run_id??'']};
 fail('Unknown working-set scope');
