async function queryRows(db,data,exporting=false){validateData(data,['revision','table'],['after_key','limit',...exporting?[]:['keys','filter','scope','operation_id','current_run_id']]);const pinned=await pin(db,data.revision),imported=await loadImport(db,pinned.import_id),{infos}=manifestInfo(imported.manifest);if(!infos.has(data.table))fail('Unknown logical table');const after=data.after_key??'',limit=data.limit??MAIN_STORE_LIMITS.rows;if(!(after===''||hash(after))||!integer(limit,MAIN_STORE_LIMITS.rows)||limit<1)fail('Invalid row page');if(data.scope&&scopes[data.scope]!==data.table)fail('Scope does not match its domain table');if(data.operation_id!==undefined&&!op(data.operation_id)||data.current_run_id!==undefined&&(typeof data.current_run_id!=='string'||data.current_run_id.length>200))fail('Invalid working-set context');const where=[],args=[];if(data.keys!==undefined){if(!Array.isArray(data.keys)||data.keys.length>500||!data.keys.every(hash)||new Set(data.keys).size!==data.keys.length)fail('Invalid exact row keys');where.push('r.key_sha256 IN (SELECT value FROM json_each(?))');args.push(JSON.stringify(data.keys));}
 if(data.filter!==undefined){const allowed=['identity','run_id','status','task_type','profile_hash','provider','updated_after','key','source','source_name','issue_key'];if(!object(data.filter)||Object.keys(data.filter).some(k=>!allowed.includes(k)||typeof data.filter[k]!=='string'||data.filter[k].length>2000))fail('Invalid domain filter');for(const [k,v]of Object.entries(data.filter)){where.push(k==='updated_after'?'r.updated_at>?':`${projectionField(k)}=?`);args.push(v);}}
 let candidates='SELECT NULL identity WHERE 0';if(data.scope==='abstract_retry'){const columns=infos.get('papers')?.columns;if(!columns||!['abstract','publication_type','eligibility_status'].every(c=>columns.includes(c)))fail('Enrichment scope needs the academic paper schema');const field=(name,suffix='v')=>`json_extract(o.envelope,'$.values[${columns.indexOf(name)}].${suffix}')`;candidates=`SELECT p.identity FROM live p CROSS JOIN ms_records o ON o.namespace='owner' AND o.record_sha256=p.record_sha256 WHERE p.table_name='papers' AND ${field('eligibility_status')}<>'excluded' AND (${field('abstract','t')}='null' OR ${field('abstract')}='' OR ${field('abstract','bytes')}=0 OR ${field('publication_type')}='Unknown' OR ${field('eligibility_status')}='quarantine')`;}const liveTables=data.scope==='abstract_retry'?['abstract_attempts','papers']:data.scope==='ui_runs'?['pipeline_runs','agent_jobs']:data.scope==='runtime_run_papers'?['run_papers','agent_jobs']:[data.table];const scoped=scopeSQL(data.scope,data);where.push('('+scoped.sql+')');args.push(...scoped.args);const raw=await all(db,`WITH live AS (${liveSQL(false)} AND r.table_name IN (SELECT value FROM json_each(?))), candidate_papers AS (${candidates}), chosen AS (SELECT r.key_sha256,r.record_sha256 FROM live r WHERE r.table_name=? AND r.key_sha256>? AND ${where.join(' AND ')} ORDER BY r.key_sha256 LIMIT ?), sized AS (SELECT c.key_sha256,o.envelope,SUM(LENGTH(CAST(o.envelope AS BLOB))) OVER(ORDER BY c.key_sha256) total,ROW_NUMBER() OVER(ORDER BY c.key_sha256) ordinal FROM chosen c CROSS JOIN ms_records o ON o.namespace=? AND o.record_sha256=c.record_sha256) SELECT key_sha256,envelope,(SELECT MAX(key_sha256) FROM chosen)>sized.key_sha256 more FROM sized WHERE total<=? AND ordinal<=? ORDER BY key_sha256`,NS,pinned.import_id,data.revision,data.revision,JSON.stringify(liveTables),data.table,after,...args,limit+1,NS,500000,limit);
 const done=!raw.length||!raw.at(-1).more;return {revision:data.revision,table:data.table,rows:raw.map(r=>JSON.parse(r.envelope)),next_key:done?null:raw.at(-1).key_sha256,done};}
async function queryFiles(db,data){validateData(data,['revision'],['paths','prefix','after_path','limit']);const pinned=await pin(db,data.revision),after=data.after_path??'',limit=data.limit??500;if(!(after===''||safePath(after))||!integer(limit,500)||!limit)fail('Invalid file page');const where=[],args=[];if(data.paths!==undefined){if(!Array.isArray(data.paths)||data.paths.length>500||!data.paths.every(safePath))fail('Invalid exact file paths');where.push('f.path IN (SELECT value FROM json_each(?))');args.push(JSON.stringify(data.paths));}if(data.prefix!==undefined){if(typeof data.prefix!=='string'||data.prefix.length>1000||data.prefix.includes('\0'))fail('Invalid file prefix');where.push('substr(f.path,1,length(?))=?');args.push(data.prefix,data.prefix);}
 const rows=await all(db,`WITH page AS (SELECT f.path,f.mode,f.bytes,f.sha256 FROM ms_files f WHERE f.namespace=? AND f.import_id=? AND f.revision<=? AND f.revision=(SELECT MAX(v.revision) FROM ms_files v WHERE v.namespace=f.namespace AND v.import_id=f.import_id AND v.path=f.path AND v.revision<=?) AND f.path>? ${where.length?'AND '+where.join(' AND '):''} ORDER BY f.path LIMIT ?), sized AS (SELECT *,SUM(LENGTH(CAST(path AS BLOB))*3+160) OVER(ORDER BY path) total,ROW_NUMBER() OVER(ORDER BY path) ordinal FROM page) SELECT path,mode,bytes,sha256,(SELECT MAX(path) FROM page)>sized.path more FROM sized WHERE total<=500000 AND ordinal<=? ORDER BY path`,NS,pinned.import_id,data.revision,data.revision,after,...args,limit+1,limit);
 const done=!rows.length||!rows.at(-1).more;return {revision:data.revision,files:rows.map(({more,...f})=>f),next_path:done?null:rows.at(-1).path,done};}
async function readManifest(db,data){validateData(data,['revision']);const pinned=await pin(db,data.revision),imported=await loadImport(db,pinned.import_id);const {objects,files,statistics,...core}=imported.manifest;return {revision:data.revision,manifest_sha256:pinned.import_id,manifest:core,watermarks:pinned.watermarks,object_count:objects?.length??null,file_count:(await first(db,'SELECT COUNT(DISTINCT path) count FROM ms_files WHERE namespace=? AND import_id=? AND revision<=?',NS,pinned.import_id,data.revision)).count};}
async function summary(db,data){validateData(data,['revision'],['operation_id']);const pinned=await pin(db,data.revision);if(data.operation_id!==undefined&&!op(data.operation_id))fail('Invalid operation ID');const rows=await all(db,`WITH live AS (${liveSQL(false)}) SELECT table_name,CAST(MAX(CAST(json_extract(projection,'$._rowid') AS INTEGER)) AS TEXT) rowid_max FROM live GROUP BY table_name`,NS,pinned.import_id,data.revision,data.revision);const counts=await first(db,`WITH live AS (${liveSQL(false)}) SELECT (SELECT COUNT(DISTINCT j.value) FROM live l,json_each(l.projection,'$._archives') j) unavailable_files,(SELECT COUNT(DISTINCT j.value) FROM live l,json_each(l.projection,'$._backups') j) local_restore_backups`,NS,pinned.import_id,data.revision,data.revision);return {revision:data.revision,rowid_maxima:Object.fromEntries(rows.map(r=>[r.table_name,r.rowid_max??'0'])),history_artifact_counts:counts,watermarks:pinned.watermarks};}
async function exportSummary(db,data){validateData(data,['revision']);const pinned=await pin(db,data.revision),imported=await loadImport(db,pinned.import_id),counts=await all(db,`WITH live AS (${liveSQL(false)}) SELECT table_name,COUNT(*) rows FROM live GROUP BY table_name`,NS,pinned.import_id,data.revision,data.revision),lookup=new Map(counts.map(r=>[r.table_name,r.rows]));const files=await first(db,'SELECT COUNT(DISTINCT path) count FROM ms_files WHERE namespace=? AND import_id=? AND revision<=?',NS,pinned.import_id,data.revision);return {revision:data.revision,tables:imported.manifest.tables.map(t=>({name:t.name,rows:lookup.get(t.name)||0})),file_count:files.count};}
async function readObject(db,data){validateData(data,['sha256']);if(!hash(data.sha256))fail('Invalid object hash');const row=await first(db,'SELECT descriptor,verified FROM ms_objects WHERE namespace=? AND sha256=?',NS,data.sha256);if(!row||!row.verified)fail('Verified object not found',404);return {object:JSON.parse(row.descriptor)};}
async function readChunk(db,data){validateData(data,['sha256']);if(!hash(data.sha256))fail('Invalid chunk hash');const row=await first(db,'SELECT sha256,bytes,data_base64 FROM ms_chunks WHERE namespace=? AND sha256=?',NS,data.sha256);if(!row)fail('Chunk not found',404);if(await sha(base64Bytes(row.data_base64))!==row.sha256)fail('Stored chunk checksum mismatch',409);return row;}
function readHashes(data){validateData(data,['sha256s']);if(!Array.isArray(data.sha256s)||!data.sha256s.length||data.sha256s.length>200||!data.sha256s.every(hash)||new Set(data.sha256s).size!==data.sha256s.length)fail('Invalid content-hash batch');}
async function readObjects(db,data){readHashes(data);const rows=await all(db,`WITH page AS (SELECT o.sha256,o.descriptor FROM json_each(?) j CROSS JOIN ms_objects o ON o.namespace=? AND o.sha256=j.value AND o.verified=1 ORDER BY o.sha256), sized AS (SELECT *,SUM(LENGTH(CAST(descriptor AS BLOB))) OVER(ORDER BY sha256) total,ROW_NUMBER() OVER(ORDER BY sha256) ordinal FROM page) SELECT descriptor FROM sized WHERE total<=500000 OR ordinal=1 ORDER BY sha256`,JSON.stringify(data.sha256s),NS);if(!rows.length)fail('Verified objects not found',404);return {objects:rows.map(r=>JSON.parse(r.descriptor))};}
async function readChunks(db,data){readHashes(data);const rows=await all(db,`WITH page AS (SELECT c.sha256,c.bytes,c.data_base64 FROM json_each(?) j CROSS JOIN ms_chunks c ON c.namespace=? AND c.sha256=j.value ORDER BY c.sha256), sized AS (SELECT *,SUM(LENGTH(data_base64)+120) OVER(ORDER BY sha256) total FROM page) SELECT sha256,bytes,data_base64 FROM sized WHERE total<=500000 ORDER BY sha256`,JSON.stringify(data.sha256s),NS);if(!rows.length)fail('Chunks not found',404);for(const row of rows)if(await sha(base64Bytes(row.data_base64))!==row.sha256)fail('Stored chunk checksum mismatch',409);return {chunks:rows};}
async function readObjectChunks(db,data){validateData(data,['revision','sha256'],['after','limit']);const pinned=await pin(db,data.revision);if(!hash(data.sha256)||!integer(data.after??0)||!integer(data.limit??1,2)||(data.limit??1)<1)fail('Invalid object page');const referenced=await first(db,`SELECT 1 present FROM ms_files f WHERE namespace=? AND import_id=? AND revision<=? AND sha256=? UNION ALL SELECT 1 FROM ms_rows r JOIN ms_records o ON o.namespace=r.namespace AND o.record_sha256=r.record_sha256,json_each(o.envelope,'$.values') v WHERE r.namespace=? AND r.import_id=? AND r.revision<=? AND json_extract(v.value,'$.ref')=? LIMIT 1`,NS,pinned.import_id,data.revision,data.sha256,NS,pinned.import_id,data.revision,data.sha256);if(!referenced)fail('Object is not referenced by the pinned dataset history',404);const {object}=await readObject(db,{sha256:data.sha256}),after=data.after??0,parts=[];for(const c of object.chunks.slice(after,after+(data.limit??1)))parts.push(await readChunk(db,{sha256:c.sha256}));return {revision:data.revision,object,chunks:parts,next:after+parts.length,done:after+parts.length>=object.chunks.length};}
async function capacity(db,data){validateData(data,[]);const sizes=await first(db,'SELECT (SELECT COALESCE(SUM(bytes),0) FROM ms_chunks WHERE namespace=?) raw_chunk_bytes,(SELECT COALESCE(SUM(LENGTH(CAST(data_base64 AS BLOB))),0) FROM ms_chunks WHERE namespace=?) stored_chunk_text_bytes,(SELECT COALESCE(SUM(LENGTH(CAST(envelope AS BLOB))),0) FROM ms_records WHERE namespace=?) record_payload_bytes,(SELECT COUNT(*) FROM ms_rows WHERE namespace=?) row_versions,(SELECT COUNT(*) FROM ms_revisions WHERE namespace=?) revisions',NS,NS,NS,NS,NS);let page_count=null,page_size=null,d1_size_after=null;try{page_count=(await db.prepare('PRAGMA page_count').first())?.page_count??null;page_size=(await db.prepare('PRAGMA page_size').first())?.page_size??null;}catch{}try{d1_size_after=(await db.prepare('SELECT 1').run()).meta?.size_after??null;}catch{}return {...sizes,page_count,page_size,allocated_sqlite_bytes:page_count&&page_size?page_count*page_size:null,d1_size_after,site_quota_bytes:null,note:'Storage observations only. Sites quota and deployment admission limits are not exposed or inferred.'};}
export const MAIN_STORE_ACTIONS=Object.freeze(['head','capacity','export_summary','put_chunks','put_objects','put_chunk','put_object','verify_objects','verify_object','begin_import','import_rows','verify_import','commit_import','read_manifest','query_rows','export_rows','query_files','export_files','summary','read_objects','read_chunks','read_object','read_chunk','read_object_chunks','begin_operation','stage_operation','verify_operation','commit_staged_operation','commit_operations']);
export async function mainStoreOperation(db,action,data={}){if(!db)fail('Main-store database unavailable',503);if(!MAIN_STORE_ACTIONS.includes(action))fail('Unknown main-store operation',404);bound(data);const handlers={head:async()=>{validateData(data,[]);return {head:await head(db)};},capacity,export_summary:exportSummary,put_chunks:putChunks,put_objects:putObjects,put_chunk:putChunk,put_object:putObject,verify_objects:verifyObjects,verify_object:verifyObject,begin_import:beginImport,import_rows:importRows,verify_import:verifyImport,commit_import:commitImport,read_manifest:readManifest,query_rows:queryRows,export_rows:(db,d)=>queryRows(db,d,true),query_files:queryFiles,export_files:queryFiles,summary,read_objects:readObjects,read_chunks:readChunks,read_object:readObject,read_chunk:readChunk,read_object_chunks:readObjectChunks,begin_operation:beginOperation,stage_operation:stageOperation,verify_operation:verifyOperation,commit_staged_operation:commitStagedOperation,commit_operations:commitOperations};const result=await handlers[action](db,data);bound(result,MAIN_STORE_LIMITS.response_bytes);return result;}
export async function handleMainStore(request,env,path=new URL(request.url).pathname){if(!isOwner(request,env))fail('Site owner sign-in required',403);if(request.method!=='POST')fail('Method not allowed',405);const origin=request.headers.get('Origin');if(origin!==null&&origin!==new URL(request.url).origin)fail('Invalid request origin',403);if((request.headers.get('Content-Type')||'').split(';')[0].trim()!=='application/json')fail('JSON required',415);const action=path.startsWith('/api/main-store/')?path.slice('/api/main-store/'.length):'';const chunks=[];let size=0;const reader=request.body?.getReader();if(reader){try{while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>MAIN_STORE_LIMITS.request_bytes){await reader.cancel();fail('Main-store request too large',413);}chunks.push(value);}}finally{reader.releaseLock();}}const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}let data;try{data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch{fail('Invalid main-store JSON');}const result=await mainStoreOperation(env.DB,action,data);return new Response(JSON.stringify(result),{headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'}});}

