const enumChecks={
 abstract_attempts:{status:['found','not_found','failed','skipped']},
 agent_jobs:{status:['exported','imported','rejected','abandoned']},
 cleanup_audits:{status:['preview','applied','restored']},
 feedback_events:{interest:['interested','not_interested'],favorite:['0','1'],reading_status:['unread','read','read_later']},
 paper_feedback:{interest:['interested','not_interested'],favorite:['0','1'],reading_status:['unread','read','read_later']},
 official_issue_checks:{status:['succeeded','partial','failed']},
 papers:{low_priority:['0','1'],needs_rescreen:['0','1'],eligibility_status:['eligible','excluded','quarantine'],published_precision:['day','month','year','unknown']},
 pipeline_runs:{status:['running','succeeded','partial','failed','abandoned']},
 profile_review_runs:{status:['no_change','suggested','accepted','dismissed']},
 profile_versions:{status:['draft','active','superseded']},
 run_papers:{role:['collected','new','candidate','selected','selected_new']},
 source_health:{status:['healthy','degraded','failed','unknown']},
 task_runs:{status:['queued','running','succeeded','partial','failed']}
};
const constraintColumns={
 abstract_attempts:['identity'],agent_jobs:['run_id'],feedback_events:['identity'],
 fulltext_files:['identity','sha256'],paper_feedback:['identity'],observations:['identity'],
 recommendation_snapshots:['identity','run_id'],run_papers:['identity'],
 pipeline_runs:['profile_version_id'],profile_review_runs:['profile_version_id'],
 profile_versions:['id','profile_hash','status'],task_runs:['task_type','status'],
 sqlite_sequence:['name','seq']
};
const rejectAcademic=message=>{throw Object.assign(new Error(message),{status:400});};
function validateAcademicManifest(manifest,activation){
 const {infos}=manifestInfo(manifest),names=Object.keys(academicColumns);
 if(infos.size!==names.length||names.some(name=>!infos.has(name)))fail('Academic manifest must contain the complete recognized table set');
 for(const name of names){const info=infos.get(name),columns=academicColumns[name],primary=name==='sqlite_sequence'?['name']:columns.filter(c=>c.pk).sort((a,b)=>a.pk-b.pk).map(c=>c.name);
  if(canonicalJSON(info.columns)!==canonicalJSON(columns.map(c=>c.name))||canonicalJSON(info.primary_key)!==canonicalJSON(primary)||info.rowid!=='rowid')fail('Academic table columns, primary key, or hidden rowid metadata differs');
  if(activation&&info.key_kind!=='primary_key')fail('Rowid-fallback datasets can be staged losslessly but are not enabled as an academic main store',409);
 }
}

// Called after generic scalar/hash verification for academic activation and
// incremental writes against the recognized schema fingerprints.
// This contract intentionally narrows SQLite's permissive affinities: new values
// use their declared storage class; null composite keys and rowid fallback are
// not supported by incremental writes. They remain losslessly importable.
export function validateAcademicRow(row,info){
 const columns=Object.hasOwn(academicColumns,row.table)?academicColumns[row.table]:null;
 if(!columns||!info||info.name!==row.table||info.key_kind!=='primary_key'||info.rowid!=='rowid'||
    JSON.stringify(info.columns)!==JSON.stringify(columns.map(c=>c.name)))rejectAcademic('Incremental writes require the recognized academic table schema');
 const primary=row.table==='sqlite_sequence'?['name']:columns.filter(c=>c.pk).sort((a,b)=>a.pk-b.pk).map(c=>c.name);
 if(JSON.stringify(info.primary_key)!==JSON.stringify(primary))rejectAcademic('Academic primary key metadata differs');
 if(!Array.isArray(row.values)||row.values.length!==columns.length||row.rowid?.t!=='integer')rejectAcademic('Academic row width or rowid is invalid');
 const constraints=new Set([...primary,...(constraintColumns[row.table]||[]),...Object.keys(enumChecks[row.table]||{})]);
 for(let i=0;i<columns.length;i++){
  const c=columns[i],v=row.values[i],required=c.not_null||primary.includes(c.name)||row.table==='sqlite_sequence';
  if(v?.t==='null'){if(required)rejectAcademic(`Academic NOT NULL constraint: ${row.table}.${c.name}`);continue;}
  const type=c.type||(c.name==='name'?'TEXT':'INTEGER');
  if(!v||v.t!==({TEXT:'text',INTEGER:'integer',REAL:'real'}[type]))rejectAcademic(`Academic storage class mismatch: ${row.table}.${c.name}`);
  if(constraints.has(c.name)&&(Object.hasOwn(v,'ref')||typeof v.v!=='string'||v.v.length>2000))rejectAcademic(`Academic constraint value must remain inline: ${row.table}.${c.name}`);
  if(enumChecks[row.table]?.[c.name]&&!enumChecks[row.table][c.name].includes(v.v))rejectAcademic(`Academic CHECK constraint: ${row.table}.${c.name}`);
 }
 const alias=columns.length&&primary.length===1?columns.find(c=>c.name===primary[0]&&c.type==='INTEGER'):null;
 if(alias&&row.values[columns.indexOf(alias)].v!==row.rowid.v)rejectAcademic('INTEGER PRIMARY KEY must equal the hidden rowid');
 if(row.table==='sqlite_sequence'){
  const name=row.values[0].v,seq=row.values[1].v;
  if(!['abstract_attempts','feedback_events','fulltext_files','profile_versions'].includes(name)||BigInt(seq)<0n)rejectAcademic('Invalid academic AUTOINCREMENT sequence');
 }
}
// The caller supplies a fixed SQL CTE named prospective, containing the complete
// candidate state after its overlay: table_name,key_sha256,projection,record_sha256.
// All projections are Worker-derived, never accepted directly from a client.
// Run this inside the head-CAS transaction or validate a frozen stage against
// expected_revision and repeat that exact revision guard in the transaction.
// EXCEPT avoids quadratic correlated FK probes over 100,000+ historical rows.
export function academicConstraintSQL(){
 return `(
 EXISTS(SELECT 1 FROM prospective WHERE record_sha256 IS NOT NULL GROUP BY table_name,json_extract(projection,'$._rowid') HAVING json_extract(projection,'$._rowid') IS NULL OR COUNT(*)>1)
 OR EXISTS(SELECT 1 FROM prospective WHERE table_name='profile_versions' AND record_sha256 IS NOT NULL GROUP BY json_extract(projection,'$.profile_hash') HAVING json_extract(projection,'$.profile_hash') IS NULL OR COUNT(*)>1)
 OR (SELECT COUNT(*) FROM prospective WHERE table_name='profile_versions' AND record_sha256 IS NOT NULL AND json_extract(projection,'$.status')='active')>1
 OR EXISTS(SELECT 1 FROM prospective WHERE table_name='fulltext_files' AND record_sha256 IS NOT NULL GROUP BY json_extract(projection,'$.identity'),json_extract(projection,'$.sha256') HAVING json_extract(projection,'$.identity') IS NULL OR json_extract(projection,'$.sha256') IS NULL OR COUNT(*)>1)
 OR EXISTS(SELECT 1 FROM prospective WHERE table_name='task_runs' AND record_sha256 IS NOT NULL AND json_extract(projection,'$.status')='running' GROUP BY json_extract(projection,'$.task_type') HAVING json_extract(projection,'$.task_type') IS NULL OR COUNT(*)>1)
 OR EXISTS(SELECT 1 FROM (
  SELECT json_extract(projection,'$.identity') AS value FROM prospective WHERE record_sha256 IS NOT NULL AND table_name IN ('abstract_attempts','feedback_events','fulltext_files','paper_feedback','run_papers','observations','recommendation_snapshots')
  EXCEPT SELECT json_extract(projection,'$.identity') FROM prospective WHERE record_sha256 IS NOT NULL AND table_name='papers'))
 OR EXISTS(SELECT 1 FROM (
  SELECT json_extract(projection,'$.profile_version_id') AS value FROM prospective WHERE record_sha256 IS NOT NULL AND table_name IN ('pipeline_runs','profile_review_runs') AND json_extract(projection,'$.profile_version_id') IS NOT NULL
  EXCEPT SELECT json_extract(projection,'$.id') FROM prospective WHERE record_sha256 IS NOT NULL AND table_name='profile_versions'))
 OR EXISTS(SELECT 1 FROM (
  SELECT json_extract(projection,'$.run_id') AS value FROM prospective WHERE record_sha256 IS NOT NULL AND table_name='agent_jobs'
  EXCEPT SELECT json_extract(projection,'$.run_id') FROM prospective WHERE record_sha256 IS NOT NULL AND table_name='pipeline_runs'))
 OR EXISTS(SELECT 1 FROM (
  SELECT json_extract(projection,'$.run_id') AS value FROM prospective WHERE record_sha256 IS NOT NULL AND table_name='recommendation_snapshots'
  EXCEPT SELECT json_extract(projection,'$.run_id') FROM prospective WHERE record_sha256 IS NOT NULL AND table_name='agent_jobs'))
 )`;
}
